            self.inner.core_token_id(),
            self.inner.frac_id(),
            self.inner.cell_id(),
            self.tracked_token@,
        )
    }

    pub closed spec fn value(self) -> T {
        *self.tracked_token@.resource().resource().value()
    }

    pub open spec fn view(self) -> T {
        self.value()
    }
}

